#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int frogJump(const vector<int>& heights) {
    int n = heights.size();
    if (n <= 1) return 0;
    int prev2 = 0, prev1 = abs(heights[1] - heights[0]);
    for (int i = 2; i < n; i++) {
        int jump1 = prev1 + abs(heights[i] - heights[i - 1]);
        int jump2 = prev2 + abs(heights[i] - heights[i - 2]);
        int cur = min(jump1, jump2);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

