#include <vector>
#include <algorithm>
using namespace std;

int knapsack01(const vector<int>& weights, const vector<int>& values, int capacity) {
    vector<int> dp(capacity + 1, 0);
    int n = weights.size();
    for (int i = 0; i < n; i++) {
        for (int cap = capacity; cap >= weights[i]; cap--) {
            dp[cap] = max(dp[cap], dp[cap - weights[i]] + values[i]);
        }
    }
    return dp[capacity];
}

