        int[] dp = new int[capacity + 1];
        int n = weights.length;
        for (int i = 0; i < n; i++) {
            for (int cap = capacity; cap >= weights[i]; cap--) {
                dp[cap] = Math.max(dp[cap], dp[cap - weights[i]] + values[i]);
            }
        }
        return dp[capacity];
    }
}

