int lcsLength(const string& a, const string& b) {
    int m = a.size(), n = b.size();
    vector<int> prev(n + 1, 0);
    for (char x : a) {
        vector<int> cur(n + 1, 0);
        for (int j = 1; j <= n; j++) {
            if (x == b[j - 1]) cur[j] = prev[j - 1] + 1;
            else cur[j] = max(prev[j], cur[j - 1]);
        }
        prev = cur;
    }
    return prev[n];
}

