class Solution {
    public static int lcsLength(String a, String b) {
        int m = a.length(), n = b.length();
        int[] prev = new int[n + 1];
        for (int i = 0; i < m; i++) {
            char x = a.charAt(i);
            int[] cur = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                if (x == b.charAt(j - 1)) cur[j] = prev[j - 1] + 1;
                else cur[j] = Math.max(prev[j], cur[j - 1]);
            }
            prev = cur;
        }
        return prev[n];
    }
}
